Looking at the demo: the grid is built from blocks separated by "line" rows/columns. Colored segments on those lines outline rectangles (in block coordinates). The output is the bounding box of those rectangles in block coordinates, each block filled with its rectangle's color, other blocks filled with the interior block color (2 in demo). For the test grid: rectangles in color 5 (rows 6–12 × cols 2–8, rows 9–18 × cols 8–14), color 0 (rows 3–6 × cols 14–20 and 20–26), color 9 (rows 9–18 × cols 20–26), interior color 7 — giving a 5×4 output.

```python
def transform(grid):
    from collections import Counter
    h = len(grid); w = len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    interior = cnt.most_common(1)[0][0]
    sep_rows = [r for r in range(h) if all(v != interior for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] != interior for r in range(h))]
    linecells = [grid[r][c] for r in sep_rows for c in range(w)] + \
                [grid[r][c] for r in range(h) for c in sep_cols]
    bg = Counter(linecells).most_common(1)[0][0]
    sri = {r: i for i, r in enumerate(sep_rows)}
    sci = {c: i for i, c in enumerate(sep_cols)}
    hunits = set(); vunits = set()
    for r in sep_rows:
        pts = sorted((sci[c], grid[r][c]) for c in range(w)
                     if c in sci and grid[r][c] != bg)
        for (i1, c1), (i2, c2) in zip(pts, pts[1:]):
            if i2 == i1 + 1 and c1 == c2:
                hunits.add((sri[r], i1, i2, c1))
    for c in sep_cols:
        pts = sorted((sri[r], grid[r][c]) for r in range(h)
                     if r in sri and grid[r][c] != bg)
        for (i1, c1), (i2, c2) in zip(pts, pts[1:]):
            if i2 == i1 + 1 and c1 == c2:
                vunits.add((sci[c], i1, i2, c1))
    rects = set()
    hu = sorted(hunits)
    for a in hu:
        r1, i1, i2, col = a
        for b in hu:
            r2, j1, j2, col2 = b
            if col == col2 and j1 == i1 and j2 == i2 and r2 > r1:
                if all((i1, k, k + 1, col) in vunits and (i2, k, k + 1, col) in vunits
                       for k in range(r1, r2)):
                    rects.add((r1, r2, i1, i2, col))
    if not rects:
        return [row[:] for row in grid]
    rmin = min(t[0] for t in rects); rmax = max(t[1] for t in rects)
    cmin = min(t[2] for t in rects); cmax = max(t[3] for t in rects)
    out = [[interior] * (cmax - cmin) for _ in range(rmax - rmin)]
    for (r1, r2, a, b, col) in rects:
        for i in range(r1, r2):
            for j in range(a, b):
                out[i - rmin][j - cmin] = col
    return out
